let registered = false;

/** Registers the bundled legacy icon collection exactly once. */
export function registerLegacyIcons(): void {
  if (registered) {
    return;
  }
  registerCollection(legacyIconCollection);
  registered = true;
}

// Importing this module makes every pd: icon available for offline rendering.
registerLegacyIcons();
